 if len(G) and min(dict(G.degree()).values(),default=0)==0:continue
 code=canon(G)
 if code not in lookup:lookup[code]=len(Ts);Ts.append(G)
L=len(Ts);sub=[0]*L
for i in sorted(range(L),key=lambda i:Ts[i].number_of_edges()):
 mask=1<<i
 for e in Ts[i].edges():
