 sub[i]=mask
contains=[0]*L
for i,mask in enumerate(sub):
 while mask:
  bit=mask&-mask;mask-=bit;j=bit.bit_length()-1;contains[j]|=1<<i
print('poset',L,'time',time.time()-start,flush=True)
