 n=len(G);dec=set();single_forbidden=0;has_match=False
 for A in range(1<<n):
  U=[u for u in G if A>>u&1];V=[u for u in G if not A>>u&1]
  F=G.subgraph(U);B=G.subgraph(V)
  if B.number_of_edges()==0 and max(dict(F.degree()).values(),default=0)<=1:has_match=True
  codea=canon(F);codeb=canon(B)
