 S=((1<<L)-1)&~single_forbidden
 ids=[i for i in range(L) if S>>i&1];maxpool=max(maxpool,len(ids))
 allow={i:S for i in ids}
 for a,b in dec:
  ma=contains[a]&S;mb=contains[b]&S
  while ma:
   bit=ma&-ma;ma-=bit;j=bit.bit_length()-1;allow[j]&=~mb
 me=-1;mw=-1;cw=[];ew=[];w=3.308789373
 for j,mask in allow.items():
