 for v in G:
  R=[u for u in G if u!=v];best=100
  for mask in range(1<<len(R)):
   U={R[i] for i in range(len(R)) if mask>>i&1}
   val=sum((a in U)==(b in U) for a,b in G.edges() if a!=v and b!=v)
   best=min(best,val)
  vals.append(best)
 if min(vals)<2:continue
