 for mask in range(1<<n):
  U=[u for u in G if mask>>u&1];V=[u for u in G if not mask>>u&1]
  if G.subgraph(V).number_of_edges():continue
  F=G.subgraph(U)
  if nx.is_forest(F):forests.append(F.copy())
 if forests:out.append((G,vals,forests))
print('graphs up to7 universal-plus-edge-free with forest decomposition',len(out))
for G,vals,Fs in out[:20]:
 print('H',len(G),list(G.edges()),'minforest',min((len(F),F.number_of_edges(),tuple(sorted(dict(F.degree()).values()))) for F in Fs))
